}

.product-price.sale {
    color: var(--warning-color);
}

.add-to-cart {
    background-color: var(--accent-color);
    border: none;
    border-radius: 6px;
    width: 40px;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
