    transition: var(--transition);
    color: var(--secondary-color);
}

.add-to-cart:hover {
    background-color: var(--accent-dark);
    transform: scale(1.1);
}

/* Deals Section */
.deals-container {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: var(--spacing-unit) * 1.5;
}

.deal-card {
