}

.newsletter-section h2 {
    font-size: 32px;
    margin-bottom: var(--spacing-unit);
}

.newsletter-section p {
    margin-bottom: calc(var(--spacing-unit) * 1.5);
    font-size: 16px;
}

.newsletter-form {
    display: flex;
    gap: var(--spacing-unit);
