    margin-bottom: calc(var(--spacing-unit) * 2);
}

.footer-section h3 {
    font-size: 16px;
    margin-bottom: var(--spacing-unit);
    font-weight: 600;
}

.footer-section p {
    color: rgba(255, 255, 255, 0.7);
    font-size: 14px;
}

.footer-section ul {
    list-style: none;
}

.footer-section ul li {
    margin-bottom: 8px;
}

.footer-section a {
    color: rgba(255, 255, 255, 0.7);
    text-decoration: none;
    transition: var(--transition);
    font-size: 14px;
}

.footer-section a:hover {
    color: var(--accent-color);
}

.social-links {
    display: flex;
    gap: var(--spacing-unit);
}

.footer-bottom {
    max-width: 1400px;
    margin: 0 auto;
    padding-top: var(--spacing-unit) * 2;
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: var(--spacing-unit);
    font-size: 13px;
    color: rgba(255, 255, 255, 0.7);
}

.footer-links {
    display: flex;
    gap: var(--spacing-unit);
}

/* Responsive Design */
@media (max-width: 768px) {
    .header-container {
        flex-wrap: wrap;
    }

    .logo {
        font-size: 20px;
        order: 1;
    }

    .nav-toggle {
        display: flex;
        order: 2;
    }

    .main-nav {
        order: 3;
        width: 100%;
        margin: var(--spacing-unit) 0 0 0;
    }

    .nav-list {
        display: none;
        flex-direction: column;
        gap: 0;
    }

    .nav-list.active {
        display: flex;
    }

    .nav-list a {
        padding: var(--spacing-unit);
        border-bottom: 1px solid var(--border-color);
    }

    .header-actions {
        order: 4;
    }

    .hero {
        grid-template-columns: 1fr;
        padding: var(--spacing-unit);
    }

    .hero-image {
        height: 250px;
    }

    .hero-content h2 {
        font-size: 28px;
    }

    .newsletter-form {
        flex-direction: column;
    }

    .newsletter-form .cta-button {
        align-self: stretch;
    }

    .footer-bottom {
        flex-direction: column;
        text-align: center;
    }

    .footer-links {
        justify-content: center;
    }

    .products-grid {
        grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    }

    .section {
        padding: calc(var(--spacing-unit) * 2) var(--spacing-unit);
    }
}

@media (max-width: 480px) {
    :root {
        --spacing-unit: 12px;
    }

    .hero-content h2 {
        font-size: 24px;
    }

    .section-header h2 {
        font-size: 22px;
    }

    .products-grid {
        grid-template-columns: 1fr;
    }

    .deals-container {
        grid-template-columns: 1fr;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .product-card:hover {
        transform: none;
    }

    .editorial-card:hover {
        transform: none;
    }
}

/* Print Styles */
@media print {
    .header,
    .footer,
    .newsletter-section,
    .cta-button,
    .secondary-button,
    .tertiary-button,
    .add-to-cart {
        display: none;
    }

    body {
        background-color: white;
    }
}
