}

.product-footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: auto;
}

.price-section {
    display: flex;
    gap: 8px;
    align-items: center;
}

.product-price {
    font-weight: 600;
    font-size: 18px;
}

.product-price.original {
    text-decoration: line-through;
    color: var(--text-secondary);
    font-size: 14px;
}

.product-price.sale {
    color: var(--warning-color);
}

.add-to-cart {
    background-color: var(--accent-color);
    border: none;
    border-radius: 6px;
    width: 40px;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: var(--transition);
    color: var(--secondary-color);
}

.add-to-cart:hover {
    background-color: var(--accent-dark);
    transform: scale(1.1);
}

