    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: var(--spacing-unit) * 1.5;
}

.deal-card {
    border-radius: var(--border-radius);
    overflow: hidden;
    position: relative;
    transition: var(--transition);
}

.deal-badge {
    position: absolute;
    top: var(--spacing-unit);
    left: var(--spacing-unit);
