// Navigation Toggle
const navToggle = document.getElementById('nav-toggle');
const navList = document.getElementById('nav-list');

navToggle.addEventListener('click', () => {
    const isExpanded = navToggle.getAttribute('aria-expanded') === 'true';
    navToggle.setAttribute('aria-expanded', !isExpanded);
    navList.classList.toggle('active');
});

// Close navigation when a link is clicked
document.querySelectorAll('.nav-list a').forEach(link => {
    link.addEventListener('click', () => {
        navToggle.setAttribute('aria-expanded', 'false');
        navList.classList.remove('active');
    });
});

// Close navigation when clicking outside
document.addEventListener('click', (e) => {
    if (!e.target.closest('.main-nav') && !e.target.closest('.nav-toggle')) {
        navToggle.setAttribute('aria-expanded', 'false');
        navList.classList.remove('active');
    }
});

// Add to Cart functionality with visual feedback
document.querySelectorAll('.add-to-cart').forEach(button => {
    button.addEventListener('click', (e) => {
        e.preventDefault();

        // Get product name from the card
        const card = button.closest('.product-card');
        const productName = card.querySelector('.product-name').textContent;
        const price = card.querySelector('.product-price:not(.original)').textContent;

        // Show feedback
        const originalHTML = button.innerHTML;
        button.innerHTML = '✓';
        button.style.backgroundColor = '#4caf50';

        // Toast notification
        showNotification(`${productName} added to cart!`);

        // Reset button after 2 seconds
        setTimeout(() => {
            button.innerHTML = originalHTML;
            button.style.backgroundColor = '';
        }, 2000);
    });
});

// Newsletter form handler
function handleNewsletterSubmit(event) {
    event.preventDefault();

    const emailInput = document.getElementById('email-input');
    const email = emailInput.value;

    // Simple email validation
    if (!isValidEmail(email)) {
        emailInput.setAttribute('aria-invalid', 'true');
        showNotification('Please enter a valid email address', 'error');
        return false;
    }

    emailInput.removeAttribute('aria-invalid');

    // Show success message
    showNotification('Thanks for subscribing! Check your inbox for a special offer.', 'success');

    // Reset form
    emailInput.value = '';

    return false;
}

// Email validation helper
function isValidEmail(email) {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
}

// Notification system
function showNotification(message, type = 'success') {
    const notification = document.createElement('div');
    notification.className = `notification notification-${type}`;
    notification.setAttribute('role', 'status');
    notification.setAttribute('aria-live', 'polite');
    notification.textContent = message;

    document.body.appendChild(notification);

    // Trigger animation
    setTimeout(() => {
        notification.classList.add('show');
    }, 10);

    // Remove after 4 seconds
    setTimeout(() => {
        notification.classList.remove('show');
        setTimeout(() => {
            notification.remove();
        }, 300);
    }, 4000);
}

// Smooth scroll for better accessibility
document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function (e) {
        const href = this.getAttribute('href');
        // Only handle if it's a section link
        if (href !== '#') {
            e.preventDefault();
            const target = document.querySelector(href);
            if (target) {
                target.scrollIntoView({ behavior: 'smooth' });
                // Set focus to the section for screen readers
                target.setAttribute('tabindex', '-1');
                target.focus();
            }
        }
    });
});

// Product card keyboard support (spacebar to add to cart)
document.querySelectorAll('.add-to-cart').forEach(button => {
    button.addEventListener('keydown', (e) => {
        if (e.code === 'Space') {
            e.preventDefault();
            button.click();
        }
    });
});

// Intersection Observer for lazy animation
const observerOptions = {
    threshold: 0.1,
    rootMargin: '0px 0px -50px 0px'
};

const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
        if (entry.isIntersecting) {
            entry.target.classList.add('visible');
        }
    });
}, observerOptions);

// Observe product cards and editorial cards for fade-in effect
document.querySelectorAll('.product-card, .editorial-card, .deal-card').forEach(card => {
    card.classList.add('observe-element');
    observer.observe(card);
});

// Handle button click actions
document.querySelectorAll('.cta-button, .secondary-button, .tertiary-button').forEach(button => {
    button.addEventListener('click', function(e) {
        // Prevent default for demo purposes
        if (this.textContent.includes('Shop') || this.textContent.includes('Subscribe')) {
            e.preventDefault();
            showNotification('Feature coming soon!', 'success');
        }
    });
});

// Search functionality (simulated)
document.querySelectorAll('.icon-button').forEach(button => {
